export class PersonClaims {
  /** The error of each claim's last refused status change, by claim id. */
  /** Whether a submit is waiting for its answer; a second submit meanwhile is ignored. */
  private submitting = false;
  /** The lock taken for the claim whose editor is open, settling true once it is held. */
  private locking: { id: number; result: Promise<boolean> } | null = null;
  protected readonly rowErrors = signal<Record<number, string>>({});
  /** The reason typed for rejecting each PENDING claim, by claim id. */
  protected readonly rejectReasons = signal<Record<number, string>>({});
  /** The date typed for deferring each OPEN claim until, by claim id. */
  protected readonly deferDates = signal<Record<number, string>>({});
  /** The new date typed for re-dating each claim, by claim id. */
  protected readonly redates = signal<Record<number, string>>({});
  /** The amount typed for splitting off each OPEN claim, by claim id. */
  protected readonly splitAmounts = signal<Record<number, string>>({});
  /** The amount typed for changing each DRAFT claim's amount in its row, by claim id. */
  protected readonly inlineAmounts = signal<Record<number, string>>({});
  }

  protected reasonChanged(id: number, reason: string): void {
    this.clearRowError(id);
    this.rejectReasons.update((rs) => ({ ...rs, [id]: reason }));
  }

  /** Reject a PENDING claim with the reason typed for it; it goes back to OPEN. */
  protected async reject(c: Claim): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const reason = (this.rejectReasons()[c.id] ?? '').trim();
    if (reason === '') {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter a reason for rejecting the claim.' }));
      return;
    }
    try {
      const claim = await this.api.reject(sheetId, c.id, reason);
      this.rejectReasons.update(({ [c.id]: _, ...rest }) => rest);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: statusError(e, c.openedBy === this.session.user()) }));
    }
  }

  /** Open, settle, approve, re-settle or void a claim; a move its status does not allow shows an error on the claim. */
  protected async changeStatus(c: Claim, action: ClaimAction): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const claim = await this.api.changeStatus(sheetId, c.id, action);
      if (this.session.sheetId() === sheetId) this.saved.emit(claim);
    } catch (e) {
      const err = action === 'resettle' ? resettleError(e) : statusError(e, c.openedBy === this.session.user());
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: err }));
    }
  }

  protected splitAmountChanged(id: number, amount: string): void {
    this.clearRowError(id);
    this.splitAmounts.update((as) => ({ ...as, [id]: amount }));
  }

  /** Split the amount typed for it off an OPEN claim; the original keeps the rest and the new
   *  claim is listed first. A refusal shows an error on the claim. */
  protected async split(c: Claim): Promise<void> {
    this.clearRowError(c.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const amount = (this.splitAmounts()[c.id] ?? '').trim();
    if (!AMOUNT_PATTERN.test(amount)) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: 'Enter an amount with up to two decimals to split off.' }));
      return;
    }
    try {
      const { original, split } = await this.api.split(sheetId, c.id, amount);
      this.splitAmounts.update(({ [c.id]: _, ...rest }) => rest);
      if (this.session.sheetId() === sheetId) {
        this.saved.emit(original);
        this.saved.emit(split);
      }
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [c.id]: splitError(e) }));
    }
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A move of a claim's status, as the server names it. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'resettle';

export interface Claim {
  id: number;
  personId: number;
  /** Always with two decimals, as the server formats it. */
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The sheet's number for the claim, given when it is opened and kept if it is voided; null while DRAFT.
   *  A sheet-wide number, or under period numbering one within its period (P1-1, X-1 in no period). */
  number: string | null;
  /** The due fixed when the claim was settled, with two decimals; null, so the due is live, for
   *  a claim not SETTLED or settled when its grade had no rate. */
  settledDue: string | null;
  /** The user who opened the claim, who cannot settle it; null while DRAFT. */
  openedBy: string | null;
  /** Whether the person's last statement bound the claim: it then shows and totals statedDue,
   *  except while PENDING, when it shows and totals its live figure. */
  stated: boolean;
  /** The due the claim was bound to, with two decimals; null when unbound or n/a then. */
  statedDue: string | null;
  /** The number of the SETTLED claim this correction (a negative amount) corrects; null for others. */
  corrects: string | null;
  /** Where the claim is listed, newest (highest) first: set when it is added, and again when it
   *  is reassigned, so a moved claim is its new person's newest. */
  listed: number;
  /** yyyy-mm-dd: fixed when the claim was created, its date plus the terms of its person's grade
   *  in force on that date; later changes to the terms or its date leave it. */
  dueBy: string;
  /** The claim's status log, oldest first: one line per status it has had. */
  log: ClaimLogLine[];
  /** yyyy-mm-dd: the date the claim was deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim has. */
  proofs: number;
  /** The number of the claim this one was split from; null when not made by a split. */
  splitFrom: string | null;
  /** The user whose open editor locks the claim for everyone else; null while unlocked. */
  lockedBy: string | null;
  /** Whether the claim was added while its period was soft-closed. */
  lateEntry: boolean;
  /** yyyy-mm-dd: the last day (the sheet's today then) the claim was reminded; null when never reminded. */
  reminded: string | null;
  /** The claim's external reference, unique on its sheet without regard to case; null when none. */
  ref: string | null;
  /** The claim's tags: lower-case, sorted and comma separated; null when none. */
  tags: string | null;
}

/** A line of a claim's status log: the status, who moved the claim there, the sheet's today then
 *  (yyyy-mm-dd), and the claim's due at that moment with two decimals (null: n/a). */
export interface ClaimLogLine {
  status: ClaimStatus;
  by: string;
  on: string;
  due: string | null;
}

